function pick(row: Partial<Record<Locale, string>> & { en: string }, locale: Locale): string {
  return row[locale] ?? row.en;
}

export function findingCopy(locale: Locale, code: string): FindingCopy | null {
  const pack = PACK[code];
  if (!pack) return null;
  const out: FindingCopy = { title: pick(pack.title, locale) };
  if (pack.detail) out.detail = pick(pack.detail, locale);
  if (pack.why) {
    const why = pick(pack.why, locale);
    if (why) out.why = why;
  }
  if (pack.fix) {
    const fix = pick(pack.fix, locale);
    if (fix) out.fix = fix;
  }
  return out;
}
